// ec-solver-worker.js
// Web Worker for EC_FieldSolver — runs off main thread, writes result to localStorage
// Crash-safe: result persisted before postMessage so reload resumes immediately.
//
// Pipeline: GPU (WebGL2 via OffscreenCanvas) → JS fallback
// Seven semantic fields: SOCIAL, COMFORT, WILD, BUILT_HEIGHT,
//                        MOVEMENT.xy, WALL, INTEREST.xyz

'use strict';

// Load supporting files
try { importScripts('/eastside-commons/ec-pattern-defs.js'); } catch(e) {
  console.warn('ec-pattern-defs.js not loaded:', e.message);
}
try { importScripts('/eastside-commons/ec-gpu-shaders.js'); } catch(e) {
  console.warn('ec-gpu-shaders.js not loaded:', e.message);
}
try { importScripts('/eastside-commons/ec-gpu-fields.js'); } catch(e) {
  console.warn('ec-gpu-fields.js not loaded:', e.message);
}

// ── GPU solve path ────────────────────────────────────────────────────────
// Returns same output contract as JS solve: {buildings, hotNodes, fieldLines, log, ...}
function solveGPU(parcels, proj, MAP, derivedG, opts, onPass) {
  const log = [];

  // Grid dimensions (same as JS path)
  const CELL_SIZE = opts.cellSize || 10;
  const GW = Math.ceil((MAP.x1 - MAP.x0) / CELL_SIZE) + 1;
  const GH = Math.ceil((MAP.y1 - MAP.y0) / CELL_SIZE) + 1;
  log.push(`GPU path: ${GW}×${GH} = ${(GW*GH).toLocaleString()} cells`);

  // Create OffscreenCanvas for WebGL2
  const canvas = new OffscreenCanvas(GW, GH);
  const gpu = new ECGpuFields(canvas, GW, GH);
  const S = self.EC_GPU_SHADERS;
  if (!S) throw new Error('EC_GPU_SHADERS not loaded');

  // ── Build static mask textures ──────────────────────────────────────────
  // EDA mask
  const edaMask = new Uint8Array(GW * GH);
  const spongeMask = new Uint8Array(GW * GH);

  // Build projected EDA polygon list
  function pip(px, py, poly) {
    let inside = false;
    for (let i=0, j=poly.length-1; i<poly.length; j=i++) {
      const [xi,yi] = poly[i], [xj,yj] = poly[j];
      if (((yi>py) !== (yj>py)) && (px < (xj-xi)*(py-yi)/(yj-yi)+xi)) inside=!inside;
    }
    return inside;
  }
  const edaPolys = parcels.filter(p=>p.is_eda && p.rings?.[0])
    .map(p => p.rings[0].map(([lon,lat]) => { const r=proj(lon,lat); return Array.isArray(r)?r:[r.x,r.y]; }));
  const spongePolys = parcels.filter(p=>p.spec==='SPONGE_PARCEL' && p.rings?.[0])
    .map(p => p.rings[0].map(([lon,lat]) => { const r=proj(lon,lat); return Array.isArray(r)?r:[r.x,r.y]; }));

  for (let cy=0; cy<GH; cy++) {
    for (let cx=0; cx<GW; cx++) {
      const px = MAP.x0 + cx*CELL_SIZE, py = MAP.y0 + cy*CELL_SIZE;
      if (edaPolys.some(poly=>pip(px,py,poly)))    edaMask[cy*GW+cx]    = 255;
      if (spongePolys.some(poly=>pip(px,py,poly))) spongeMask[cy*GW+cx] = 255;
    }
  }
  gpu.uploadMask('EDA_MASK', edaMask);
  gpu.uploadMask('SPONGE_MASK', spongeMask);

  // Activity node proximity mask (for invariant height cap)
  // Gaussian falloff from TIDE and CIVIC_700 centroids
  const nodeProx = new Float32Array(GW * GH);
  const nodeSeeds = [];
  for (const p of parcels) {
    if ((p.spec === 'CIVIC_700' || p.spec === 'CIVIC_SPINE_S') && p.centroid) {
      const r = proj(p.centroid.lon, p.centroid.lat);
      nodeSeeds.push(Array.isArray(r) ? r : [r.x, r.y]);
    }
  }
  const derivedTide = derivedG.TIDE;
  if (derivedTide) nodeSeeds.push([derivedTide.x+derivedTide.w/2, derivedTide.y+derivedTide.h/2]);
  for (let i=0; i<nodeProx.length; i++) {
    const px=MAP.x0+(i%GW)*CELL_SIZE, py=MAP.y0+Math.floor(i/GW)*CELL_SIZE;
    let v=0;
    for (const [nx,ny] of nodeSeeds) {
      const d2=(px-nx)**2+(py-ny)**2;
      v+=Math.exp(-3*d2/(300*300));
    }
    nodeProx[i]=Math.min(1,v);
  }
  // Upload node prox as float texture
  const gl = gpu.gl;
  gl.bindTexture(gl.TEXTURE_2D, gpu.textures['NODE_PROX']);
  gl.texImage2D(gl.TEXTURE_2D, 0, gl.R32F, GW, GH, 0, gl.RED, gl.FLOAT, nodeProx);

  // ── Build IC uniforms from derivedG ─────────────────────────────────────
  // Encode all geometry as gaussian seeds (no named constants at shader time)
  const seeds = [];
  function addSeed(ftX, ftY, r, social=0, wild=0, built=0, mvx=0, mvy=0, intZ=0) {
    seeds.push({ x:(ftX-MAP.x0)/(MAP.x1-MAP.x0), y:(ftY-MAP.y0)/(MAP.y1-MAP.y0),
                 r:r/CELL_SIZE, social, wild, built, mvx, mvy, intZ });
  }

  const sg = derivedG.SPONGE, ti = derivedG.TIDE, s = derivedG.SPINE;
  const rs = derivedG.RESEARCH;

  // Transit node (TIDE) → social seed, movement inflow
  if (ti) addSeed(ti.x+ti.w/2, ti.y+ti.h/2, 220, 0.8, 0, 0, 0, 0.4, 0);
  // Civic anchor → social + INTEREST.z
  for (const p of parcels) {
    if (p.spec==='CIVIC_700' && p.centroid) {
      const [cx,cy] = proj(p.centroid.lon, p.centroid.lat);
      addSeed(cx, cy, 180, 0.6, 0, 100, 0, 0, 1.2); // built=100 = existing building marker
    }
    if (p.spec==='HOUSING_A_530' && p.centroid) {
      const [cx,cy] = proj(p.centroid.lon, p.centroid.lat);
      addSeed(cx, cy, 100, 0, 0, 100, 0, 0, 0); // existing building marker
    }
  }
  // Sponge → wild seed (supplemented by sponge mask)
  if (sg) addSeed(sg.cx, sg.cy, Math.max(sg.rx,sg.ry)*1.2, 0, 0.9, 0, 0, 0, 0);
  // Road interfaces → movement seeds
  // N Military Hwy (west edge, mid-height): eastward inflow
  addSeed(MAP.x0+60, (MAP.y0+MAP.y1)/2, 120, 0, 0, 0, 0.6, 0, 0);
  // Tidewater Dr (east edge, mid-height): westward inflow
  addSeed(MAP.x1-60, (MAP.y0+MAP.y1)/2, 120, 0, 0, 0, -0.6, 0, 0);
  // Research zone → moderate social east side
  if (rs) addSeed(rs.x+rs.w/2, rs.y+rs.h/2, 160, 0.4, 0, 0, 0, 0, 0.3);

  // Pack seeds into parallel arrays (max 16)
  const maxSeeds = Math.min(seeds.length, 16);
  const icU = {
    uNumSeeds: maxSeeds,
    uSeedPos:    seeds.slice(0,maxSeeds).flatMap(s=>[s.x,s.y]),
    uSeedR:      seeds.slice(0,maxSeeds).map(s=>s.r),
    uSeedSocial: seeds.slice(0,maxSeeds).map(s=>s.social),
    uSeedWild:   seeds.slice(0,maxSeeds).map(s=>s.wild),
    uSeedBuilt:  seeds.slice(0,maxSeeds).map(s=>s.built),
    uSeedMvX:    seeds.slice(0,maxSeeds).map(s=>s.mvx),
    uSeedMvY:    seeds.slice(0,maxSeeds).map(s=>s.mvy),
    uSeedIntZ:   seeds.slice(0,maxSeeds).map(s=>s.intZ),
  };

  // ── Initialise GPU fields ────────────────────────────────────────────────
  gpu.init(icU);
  log.push(`IC: ${maxSeeds} seeds`);

  // ── Main solve loop ──────────────────────────────────────────────────────
  const MAX_PASSES = opts.passes || 8;
  const patternOrder = S.PATTERN_ORDER; // descending by id

  let snapshots = [];
  let allFieldLines = [];
  let prevSocialSum = null;
  let saturatedAt = null;

  const invariantU = {
    uFourStoryFt:  48.0,
    uNodeHeightFt: 96.0,
  };

  for (let pass = 0; pass < MAX_PASSES; pass++) {
    log.push(`Pass ${pass+1}/${MAX_PASSES}`);

    // Recompute wall-distance texture
    gpu.runWallDistance({ uWallThreshold: 0.2 });

    // Run each pattern: detector → modulator → invariant (interleaved)
    for (const pid of patternOrder) {
      const pdef = S.patterns[pid];
      if (!pdef) continue;

      // Pattern-specific uniforms
      const pu = {
        uWeight:    1.0,
        uNbhdR:     pdef.nbhdR || 4.0,
        uPatternId: pid,          // written to PID texture by modulator
        ...pdef.uniforms,
      };

      // Look up weight from EC_PATTERN_DEFS
      const defEntry = (self.EC_PATTERN_DEFS || []).find(d => d.id === pid);
      if (defEntry && defEntry.weight !== undefined) pu.uWeight = defEntry.weight;
      if (defEntry && defEntry.enabled === false) continue;

      gpu.runPattern(pid, pdef.detect, pdef.modulate, pu);
      gpu.runInvariant(invariantU);
    }

    // Convergence: read back SOCIAL channel, compare sum
    const fields = gpu.readback();
    const socialSum = fields.social.reduce((a,b)=>a+b, 0);
    const delta = prevSocialSum !== null ? Math.abs(socialSum - prevSocialSum) / (GW*GH) : null;
    if (delta !== null) {
      log.push(`  Δ_social=${delta.toFixed(5)}`);
      if (delta < (opts.eps || 0.008) && pass >= 2) {
        saturatedAt = pass + 1;
        log.push(`  ✓ Saturated at pass ${saturatedAt}`);
      }
    }
    prevSocialSum = socialSum;

    // Extract buildings from BUILT_HEIGHT + WALL fields (GPU readback)
    const buildings = extractBuildingsFromFields(fields, GW, GH, CELL_SIZE, MAP, edaMask);
    const hotNodes  = extractHotNodesFromFields(fields, GW, GH, CELL_SIZE, MAP);

    snapshots.push({ pass, buildings, hotNodes, saturated: !!saturatedAt });
    allFieldLines = []; // field lines derived from MOVEMENT field (future pass)

    if (typeof onPass === 'function') {
      onPass(pass, delta, !!saturatedAt, allFieldLines, log);
    }

    if (saturatedAt) break;
  }

  // Final field state
  const fields = gpu.readback();
  const buildings = extractBuildingsFromFields(fields, GW, GH, CELL_SIZE, MAP, edaMask);
  const hotNodes  = extractHotNodesFromFields(fields, GW, GH, CELL_SIZE, MAP);

  // Also export per-pattern buffers for debugging
  const patternFields = {};
  for (const pid of patternOrder) {
    const buf = gpu.readbackPattern(pid);
    if (buf) patternFields[pid] = buf;
  }

  log.push(`Done: ${buildings.length} buildings, ${hotNodes.length} hot nodes`);
  if (!saturatedAt) log.push('Max passes reached without saturation');

  return {
    snapshots, fieldLines: allFieldLines, hotNodes, buildings,
    log, gw: GW, gh: GH, cellSize: CELL_SIZE, MAP,
    saturatedAt,
    fields,         // raw field buffers for viewer
    patternFields,  // per-pattern detector buffers for debugging
    patternColors: Object.fromEntries(
      (self.EC_PATTERN_DEFS||[]).map(d=>[d.id, '#c87818']) // colour by use class later
    ),
    patternNames: Object.fromEntries(
      (self.EC_PATTERN_DEFS||[]).map(d=>[d.id, d.name])
    ),
  };
}

// ── Extract buildings from GPU field readback ─────────────────────────────
// Clusters BUILT_HEIGHT > threshold into building footprints.
function extractBuildingsFromFields(fields, gw, gh, cellSize, MAP, edaMask) {
  const BUILT_THRESH = 8.0; // ft — minimum height to be a building
  const built  = fields.built_height;
  const social = fields.social;
  const pid    = fields.pid;  // per-cell pattern-id texture

  // Single-linkage clustering on built cells
  const visited = new Uint8Array(gw * gh);
  const clusters = [];

  for (let i = 0; i < built.length; i++) {
    if (built[i] < BUILT_THRESH || visited[i] || !edaMask[i]) continue;
    const cluster = [];
    const queue = [i];
    visited[i] = 1;
    while (queue.length) {
      const idx = queue.shift();
      cluster.push(idx);
      const cx = idx % gw, cy = Math.floor(idx / gw);
      for (const [dx, dy] of [[-1,0],[1,0],[0,-1],[0,1]]) {
        const nx = cx+dx, ny = cy+dy;
        if (nx<0||ny<0||nx>=gw||ny>=gh) continue;
        const ni = ny*gw+nx;
        if (!visited[ni] && built[ni] >= BUILT_THRESH && edaMask[ni]) {
          visited[ni] = 1;
          queue.push(ni);
        }
      }
    }
    if (cluster.length >= 2) clusters.push(cluster);
  }

  const FT = cellSize;
  return clusters.map(cells => {
    let minX=Infinity, maxX=-Infinity, minY=Infinity, maxY=-Infinity;
    let sumH = 0, sumS = 0;
    const pidTally = {};
    for (const idx of cells) {
      const cx = idx % gw, cy = Math.floor(idx / gw);
      const px = MAP.x0 + cx*FT, py = MAP.y0 + cy*FT;
      if (px < minX) minX = px; if (px > maxX) maxX = px;
      if (py < minY) minY = py; if (py > maxY) maxY = py;
      sumH += built[idx];
      sumS += social[idx];
      // Tally pattern ids — use rounded PID value
      if (pid) {
        const p = Math.round(pid[idx]);
        if (p > 0) pidTally[p] = (pidTally[p] || 0) + 1;
      }
    }
    const avgH = sumH / cells.length;
    // domPid: most frequent pattern id that wrote BUILT_HEIGHT to this cluster
    let domPid = null;
    if (Object.keys(pidTally).length > 0) {
      domPid = Number(Object.entries(pidTally).sort((a,b) => b[1]-a[1])[0][0]);
    } else {
      // Fallback: classify by social level
      const avgS = sumS / cells.length;
      domPid = avgS > 0.65 ? 44 : avgS > 0.4 ? 87 : 37;
    }
    return {
      x: minX, y: minY,
      w: maxX - minX + FT,
      h: maxY - minY + FT,
      pts: cells.length,
      avgStrong: avgH / 12,
      domPid,
    };
  }).filter(b => b.w > 8 && b.h > 8);
}

// ── Extract hot nodes from GPU field readback ─────────────────────────────
// Hot nodes = local maxima of combined SOCIAL × |MOVEMENT|
function extractHotNodesFromFields(fields, gw, gh, cellSize, MAP) {
  const social = fields.social;
  const mvx = fields.movement_x, mvy = fields.movement_y;
  const iz = fields.interest_z;
  const nodes = [];

  for (let cy=1; cy<gh-1; cy++) {
    for (let cx=1; cx<gw-1; cx++) {
      const i = cy*gw+cx;
      const v = social[i] * (Math.sqrt(mvx[i]**2+mvy[i]**2)*0.5 + iz[i]*0.5);
      if (v < 0.1) continue;
      // Local maximum check (3×3)
      let isMax = true;
      for (let dy=-1; dy<=1 && isMax; dy++) {
        for (let dx=-1; dx<=1 && isMax; dx++) {
          if (!dx&&!dy) continue;
          const ni=(cy+dy)*gw+(cx+dx);
          const nv=social[ni]*(Math.sqrt(mvx[ni]**2+mvy[ni]**2)*0.5+iz[ni]*0.5);
          if (nv >= v) isMax=false;
        }
      }
      if (isMax) {
        nodes.push({
          x: MAP.x0+cx*cellSize,
          y: MAP.y0+cy*cellSize,
          v, nStrong: Math.round(v*10),
          weights: { social: social[i], movement: Math.sqrt(mvx[i]**2+mvy[i]**2) },
        });
      }
    }
  }
  // Thin to sparse set (one per 120ft cluster)
  return nodes.sort((a,b)=>b.v-a.v).filter((n,i,arr)=>{
    if (i===0) return true;
    return !arr.slice(0,i).some(m=>Math.hypot(m.x-n.x,m.y-n.y)<120);
  }).slice(0, 300);
}



